import{_ as a,o,c as d,a2 as i}from"./chunks/framework.CqGPl1zp.js";const p="/newx-doc/assets/%E5%B7%A5%E4%BD%9C%E5%8F%B0.BYC3avVJ.png",h=JSON.parse('{"title":"移动端 PMS","description":"","frontmatter":{},"headers":[],"relativePath":"pms/mobile.md","filePath":"pms/mobile.md","lastUpdated":null}'),c={name:"pms/mobile.md"};function s(l,e,t,r,n,m){return o(),d("div",null,[...e[0]||(e[0]=[i('<h1 id="移动端-pms" tabindex="-1">移动端 PMS <a class="header-anchor" href="#移动端-pms" aria-label="Permalink to &quot;移动端 PMS&quot;">​</a></h1><p>友情提示</p><p>本文讲解 yudao 移动端（uni-app 版）的 PMS 系统，重点说清楚两件事：PMS 已经提供手机端、当前支持的主要功能。</p><ul><li>仓库：<a href="https://github.com/yudaocode/yudao-ui-admin-uniapp" target="_blank" rel="noreferrer">https://github.com/yudaocode/yudao-ui-admin-uniapp</a>，基于 <code>uni-app</code> + <code>Vue3</code> + <code>wot-ui</code> 实现，支持 H5、微信小程序等多端。</li><li>后端：复用 PC 端同一套 <code>yudao-module-pms</code> 模块与 <code>/pms/**</code> 接口，移动端只是换了一层 UI。</li></ul><h2 id="_1-移动端功能" tabindex="-1">1. 移动端功能 <a class="header-anchor" href="#_1-移动端功能" aria-label="Permalink to &quot;1. 移动端功能&quot;">​</a></h2><ul><li>项目中心：工作台、我的项目、项目分组、归档项目、项目回收站、项目模板。</li><li>项目详情：项目概况、待规划、项目工时，以及项目设置中的基本信息、成员、公告和协作配置。</li><li>迭代：迭代列表、新建与编辑迭代、迭代详情。</li><li>工作项：工作项列表、新增与编辑、详情、评论、动态、子工作项、工时登记、状态设置和标签管理。</li><li>知识中心：知识库、文档搜索、文档标签、我的关注、最近使用、回收站、知识库模板。</li><li>知识库工作区：知识库主页、目录树、文件夹、富文本文档、文件上传、移动、成员管理、内容协作权限、文档评论和文档分享。</li></ul><p><img src="'+p+'" alt="PMS 移动端工作台"></p><p>进入工作台后，点击「PMS 项目管理」即可看到移动端 PMS 的功能分组；页面路由为 <code>/pages/index/index</code>，PMS 菜单由 <code>src/pages/index/menu.json</code> 配置，菜单项同样按 <code>pms:pm:*</code>、<code>pms:kb:*</code> 按钮权限过滤。</p><p>移动端页面统一位于 <code>src/pages-pms</code> 下，并通过 <code>src/api/pms</code> 调用后端接口。项目、迭代、工作项相关页面在 <code>pages-pms/pm</code>，知识库和文档相关页面在 <code>pages-pms/kb</code>。</p><h2 id="_2-启动与发布" tabindex="-1">2. 启动与发布 <a class="header-anchor" href="#_2-启动与发布" aria-label="Permalink to &quot;2. 启动与发布&quot;">​</a></h2><ul><li>启动：参考 <a href="./../quick-start-front">《快速启动【前端】》</a> 文档的「1.4 Vue3 + uni-app 版本」小节，在 <code>yudao-ui-admin-uniapp-next-v4</code> 仓库执行 <code>pnpm dev:h5</code>，即可启动 H5 调试页面。</li><li>发布：参考 <a href="./../admin-uniapp/deploy">《运行发布》</a> 文档；根据 uni-app 的目标平台执行 H5、微信小程序或 App 构建。</li></ul><p>启动完成后，在工作台选择「PMS 项目管理」即可进入移动端 PMS；页面路由使用 <code>/pages-pms/**</code>，例如工作台为 <code>/pages-pms/pm/workbench/index</code>，知识库列表为 <code>/pages-pms/kb/library/index</code>。</p><h2 id="_3-代码位置" tabindex="-1">3. 代码位置 <a class="header-anchor" href="#_3-代码位置" aria-label="Permalink to &quot;3. 代码位置&quot;">​</a></h2><ul><li>页面：<code>src/pages-pms/pm/</code>（工作台、项目、迭代、工作项）、<code>src/pages-pms/kb/</code>（知识库、文档、标签、关注、最近使用、回收站）</li><li>接口：<code>src/api/pms/</code></li><li>菜单配置：<code>src/pages/index/menu.json</code> 的 <code>pms</code> 分组</li></ul>',14)])])}const _=a(c,[["render",s]]);export{h as __pageData,_ as default};
